  label: string;
  options: readonly string[];
  value: string;
  onChange: (value: string) => void;
  required?: boolean;
  disabled?: boolean;
  showAllOnEmpty?: boolean;
  validate?: (value: string) => string | null;
};

const ROW_HEIGHT = 36;
const MAX_HEIGHT = 216;
const OVERSCAN = 3;
const normalize = (s: string) => s.trim().toLowerCase();

export function Input({
  label,
  options,
  value,
  onChange,
  required = false,
  disabled = false,
  showAllOnEmpty = false,
  validate,
}: InputProps) {
  const id = useId();
  const listId = `${id}-list`;
  const errorId = `${id}-error`;
  const listRef = useRef<HTMLDivElement>(null);

  const [open, setOpen] = useState(false);
  const [touched, setTouched] = useState(false);
  const [active, setActive] = useState(-1);
  const [scrollTop, setScrollTop] = useState(0);

  // Deduplicate case-insensitive equivalent options.
  const indexed = useMemo(() => {
    const seen = new Set<string>();
    return options.flatMap((label) => {
      const key = normalize(label);
      if (!key || seen.has(key)) return [];
      seen.add(key);
      return [{ label, key }];
    });
  }, [options]);

  const allowed = useMemo(
    () => new Set(indexed.map((option) => option.key)),
    [indexed]
  );

  const query = normalize(value);
  const matches = useMemo(
    () =>
      !query && !showAllOnEmpty
        ? []
        : indexed.filter((option) => option.key.includes(query)),
    [indexed, query, showAllOnEmpty]
  );

  const error =
    required && !query
      ? "This field is required."
      : validate
        ? validate(value)
        : query && !allowed.has(query)
          ? "Choose a value from the available options."
          : null;

  const invalid = touched && error !== null;
  const visible = open && !disabled && matches.length > 0;
  const height = Math.min(MAX_HEIGHT, matches.length * ROW_HEIGHT);

  // Reset both the DOM scroll position and virtualizer state after filtering.
  useLayoutEffect(() => {
    setActive(-1);
    setScrollTop(0);
    if (listRef.current) listRef.current.scrollTop = 0;
  }, [matches, visible]);

  useLayoutEffect(() => {
    const list = listRef.current;
    if (!list || active < 0) return;

    const top = active * ROW_HEIGHT;
    const bottom = top + ROW_HEIGHT;
    if (top < list.scrollTop) list.scrollTop = top;
    else if (bottom > list.scrollTop + height) {
      list.scrollTop = bottom - height;
    }
    setScrollTop(list.scrollTop);
  }, [active, height]);

  const start = Math.max(
    0,
    Math.min(
      Math.floor(scrollTop / ROW_HEIGHT) - OVERSCAN,
      matches.length - 1
    )
  );
  const end = Math.min(
    matches.length,
    start + Math.ceil(height / ROW_HEIGHT) + 2 * OVERSCAN
  );

  const renderedIndices = Array.from(
    { length: Math.max(0, end - start) },
    (_, offset) => start + offset
  );

  // Keep aria-activedescendant mounted even before scrolling catches up.
  if (
    active >= 0 &&
    active < matches.length &&
    !renderedIndices.includes(active)
  ) {
    renderedIndices.push(active);
  }

  function select(index: number) {
    const option = matches[index];
    if (!option || disabled) return;
    onChange(option.label);
    setTouched(true);
    setOpen(false);
    setActive(-1);
  }

  return (
    <div style={{ position: "relative", width: 320, maxWidth: "100%" }}>
      <label htmlFor={id}>{label}</label>
      <input
        id={id}
        role="combobox"
        aria-autocomplete="list"
        aria-expanded={visible}
        aria-controls={visible ? listId : undefined}
        aria-activedescendant={
          visible && active >= 0 && active < matches.length
            ? `${listId}-${active}`
            : undefined
        }
        aria-invalid={invalid}
        aria-describedby={invalid ? errorId : undefined}
        required={required}
        disabled={disabled}
        autoComplete="off"
        value={value}
        onFocus={() => setOpen(true)}
        onBlur={() => {
          setTouched(true);
          setOpen(false);
          setActive(-1);
        }}
        onChange={(event) => {
          onChange(event.target.value);
          setActive(-1);
          setOpen(true);
        }}
        onKeyDown={(event) => {
          if (
            event.nativeEvent.isComposing ||
            event.ctrlKey ||
            event.metaKey ||
            event.altKey
          ) return;

          if (event.key === "Escape") {
            if (visible) event.preventDefault();
            setOpen(false);
            setActive(-1);
          } else if (event.key === "Tab") {
            setOpen(false);
          } else if (
            event.key === "ArrowDown" ||
            event.key === "ArrowUp"
          ) {
            if (!matches.length) return;
            event.preventDefault();
            setOpen(true);

            // Opening starts without a selection; subsequent arrows navigate.
            if (!visible) return;
            setActive((previous) =>
              event.key === "ArrowDown"
                ? (previous + 1) % matches.length
                : previous <= 0
                  ? matches.length - 1
                  : previous - 1
            );
          } else if (
            event.key === "Enter" &&
            visible &&
            active >= 0 &&
            active < matches.length
          ) {
            event.preventDefault();
            select(active);
          }
        }}
        style={{
          display: "block",
          boxSizing: "border-box",
          width: "100%",
          padding: 8,
          border: `2px solid ${invalid ? "#dc2626" : "#9ca3af"}`,
          borderRadius: 4,
        }}
      />

      {visible && (
        <div
          ref={listRef}
          id={listId}
          role="listbox"
          aria-label={`${label} suggestions`}
          onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
          style={{
            position: "absolute",
            width: "100%",
            height,
            overflowY: "auto",
            background: "white",
            boxShadow: "0 2px 8px #0003",
            zIndex: 10,
          }}
        >
          <div
            role="presentation"
            style={{
              position: "relative",
              height: matches.length * ROW_HEIGHT,
            }}
          >
            {renderedIndices.map((index) => (
              <div
                key={matches[index].key}
                id={`${listId}-${index}`}
                role="option"
                aria-selected={active === index}
                aria-posinset={index + 1}
                aria-setsize={matches.length}
                // Preserve input focus; select on click, not pointer-down,
                // so a touch scrolling gesture does not select a row.
                onMouseDown={(event) => event.preventDefault()}
                onClick={() => select(index)}
                style={{
                  position: "absolute",
                  top: index * ROW_HEIGHT,
                  height: ROW_HEIGHT,
                  width: "100%",
                  boxSizing: "border-box",
                  padding: "8px 12px",
                  overflow: "hidden",
                  whiteSpace: "nowrap",
                  textOverflow: "ellipsis",
                  cursor: "pointer",
                  background: active === index ? "#dbeafe" : "white",
                }}
              >
                {matches[index].label}
              </div>
            ))}
          </div>
        </div>
      )}

      {invalid && <div id={errorId} role="alert">{error}</div>}
    </div>
  );
}
```

