            $"ID: {StudentID} | Name: {Name} | GPA: {GPA:F2}";
    }

    public static class StudentDB
    {
        private const string Dir = @"C:\C#\files\";
        private const string Path = Dir + "Students.dat";

        public static void SaveStudents(List<Student> students)
        {
            Directory.CreateDirectory(Dir);

            // Dispose the writer and its underlying stream, even on error.
            using BinaryWriter binaryOut = new(
                new FileStream(Path, FileMode.Create, FileAccess.Write));

            foreach (Student student in students)
            {
                binaryOut.Write(student.StudentID);
                binaryOut.Write(student.Name);
                binaryOut.Write(student.GPA);
            }
        }

        public static List<Student> GetStudents()
        {
            List<Student> students = new();
            Directory.CreateDirectory(Dir);

            if (!File.Exists(Path))
                return students;

            using BinaryReader binaryIn = new(
                new FileStream(Path, FileMode.Open, FileAccess.Read));

            // Check byte position, not PeekChar: records begin with an integer.
            while (binaryIn.BaseStream.Position < binaryIn.BaseStream.Length)
            {
                // Field order and types must match SaveStudents exactly.
                students.Add(new Student
                {
                    StudentID = binaryIn.ReadInt32(),
                    Name = binaryIn.ReadString(),
                    GPA = binaryIn.ReadDecimal()
                });
            }

            return students;
        }
    }

    public static class Validator
    {
        public static string LineEnd { get; set; } = Environment.NewLine;

        public static string IsPresent(string value, string name) =>
            string.IsNullOrWhiteSpace(value)
                ? $"{name} is a required field.{LineEnd}"
                : "";

        public static string IsInt32(string value, string name) =>
            int.TryParse(value, out _)
                ? ""
                : $"{name} must be a valid integer.{LineEnd}";

        public static string IsDecimal(string value, string name) =>
            decimal.TryParse(value, out _)
                ? ""
                : $"{name} must be a valid decimal.{LineEnd}";

        public static string IsWithinRange(
            string value, string name, decimal min, decimal max)
        {
            return decimal.TryParse(value, out decimal number)
                && (number < min || number > max)
                ? $"{name} must be between {min} and {max}.{LineEnd}"
                : "";
        }
    }

    public class StudentForm : Form
    {
        private readonly TextBox txtID = new() { Dock = DockStyle.Fill };
        private readonly TextBox txtName = new() { Dock = DockStyle.Fill };
        private readonly TextBox txtGPA = new() { Dock = DockStyle.Fill };

        private readonly ListBox lstStudents = new()
        {
            Dock = DockStyle.Fill,
            HorizontalScrollbar = true
        };

        public StudentForm()
        {
            Text = "Student Binary Data";
            ClientSize = new Size(580, 380);
            MinimumSize = new Size(480, 340);
            StartPosition = FormStartPosition.CenterScreen;

            TableLayoutPanel layout = new()
            {
                Dock = DockStyle.Fill,
                Padding = new Padding(12),
                ColumnCount = 2,
                RowCount = 5
            };

            layout.ColumnStyles.Add(
                new ColumnStyle(SizeType.Absolute, 120));
            layout.ColumnStyles.Add(
                new ColumnStyle(SizeType.Percent, 100));

            for (int row = 0; row < 3; row++)
                layout.RowStyles.Add(
                    new RowStyle(SizeType.Absolute, 38));

            layout.RowStyles.Add(new RowStyle(SizeType.Absolute, 44));
            layout.RowStyles.Add(new RowStyle(SizeType.Percent, 100));

            layout.Controls.Add(new Label
                { Text = "Student ID:", AutoSize = true }, 0, 0);
            layout.Controls.Add(txtID, 1, 0);

            layout.Controls.Add(new Label
                { Text = "Name:", AutoSize = true }, 0, 1);
            layout.Controls.Add(txtName, 1, 1);

            layout.Controls.Add(new Label
                { Text = "GPA (0–4):", AutoSize = true }, 0, 2);
