void AMyGameMode::BeginPlay()
{
    Super::BeginPlay();

    // A dedicated server should not attempt local microphone capture.
    if (GetNetMode() == NM_DedicatedServer)
    {
        return;
    }

    // The factory creates AND initializes the capture object.
    MicCapture = UAudioCaptureFunctionLibrary::CreateAudioCapture();

    if (!MicCapture)
    {
