**1. Add this helper outside the classes:**

```javascript
function highlightQuotedText(root) {
	const runs = [];
	let currentRun = [];

	const excluded = /^(CODE|PRE|SCRIPT|STYLE|TEXTAREA)$/;
	const block = /^(ADDRESS|ARTICLE|ASIDE|BLOCKQUOTE|DIV|DL|DT|DD|FIGURE|FIGCAPTION|FOOTER|HEADER|H[1-6]|HR|LI|MAIN|NAV|OL|P|SECTION|TABLE|THEAD|TBODY|TFOOT|TR|TD|TH|UL)$/;

	function flush() {
		if (currentRun.length) {
			runs.push(currentRun);
			currentRun = [];
		}
	}

	// Collect text before changing the DOM. Inline elements remain
	// in the same run; block elements and code create boundaries.
	function visit(node) {
		if (node.nodeType === Node.TEXT_NODE) {
			currentRun.push(node);
			return;
		}

		if (node.nodeType !== Node.ELEMENT_NODE) {
			return;
		}

		if (excluded.test(node.tagName) || node.tagName === "BR") {
			flush();
			return;
		}

		const boundary = block.test(node.tagName);
		if (boundary) flush();

		for (const child of node.childNodes) {
			visit(child);
		}

		if (boundary) flush();
	}

	visit(root);
	flush();

	for (const nodes of runs) {
		const text = nodes.map(node => node.data).join("");
		const ranges = Array.from(
			text.matchAll(/"[^"]*"|“[^”]*”/g),
			match => [match.index, match.index + match[0].length]
		);

		let offset = 0;

		for (const node of nodes) {
			const start = offset;
			offset += node.data.length;

			const overlaps = ranges
				.filter(([a, b]) => a < offset && b > start)
				.map(([a, b]) => [
					Math.max(a, start) - start,
					Math.min(b, offset) - start
				]);

			if (!overlaps.length) continue;

			const fragment = document.createDocumentFragment();
			let position = 0;

			for (const [a, b] of overlaps) {
				fragment.append(document.createTextNode(
					node.data.slice(position, a)
				));

				const span = document.createElement("span");
				span.style.color = "red";
				span.textContent = node.data.slice(a, b);
				fragment.append(span);

				position = b;
			}

			fragment.append(document.createTextNode(
				node.data.slice(position)
			));

			node.replaceWith(fragment);
		}
	}
}
```

