This runs after sanitization and before the `md-render` event.

**2. Add this method inside `MarkdownBlock`:**

```js
_highlightQuotedText() {
	const excluded = new Set([
		"CODE", "PRE", "SCRIPT", "STYLE", "TEXTAREA",
		"MD-BLOCK", "MD-SPAN"
	]);

	// Do not match opening and closing quotes across block boundaries.
	const blocks = new Set([
		"ADDRESS", "ARTICLE", "ASIDE", "BLOCKQUOTE", "DIV",
		"DL", "DT", "DD", "FIGURE", "FIGCAPTION",
		"FOOTER", "HEADER", "MAIN", "NAV", "SECTION",
		"P", "H1", "H2", "H3", "H4", "H5", "H6",
		"UL", "OL", "LI", "TABLE", "THEAD", "TBODY",
		"TFOOT", "TR", "TD", "TH", "HR"
	]);

	let run = [];

	function flush() {
		if (!run.length) return;

		let text = "";
		const entries = run.map(node => {
			const start = text.length;
			text += node.data;
			return { node, start, end: text.length };
		});

		const matches = [...text.matchAll(/"[^"]+"|“[^”]+”/g)];

		// Work backwards so splitting nodes preserves earlier offsets.
		for (const match of matches.reverse()) {
			const start = match.index;
			const end = start + match[0].length;

			for (let i = entries.length - 1; i >= 0; i--) {
				const entry = entries[i];
				const from = Math.max(start, entry.start);
				const to = Math.min(end, entry.end);

				if (from >= to) continue;

				const selected = entry.node.splitText(from - entry.start);
				selected.splitText(to - from);

				const span = document.createElement("span");
				span.style.color = "red";
				selected.replaceWith(span);
				span.append(selected);
			}
		}

		run = [];
	}

	function visit(parent) {
		// Snapshot the children because flush() can modify the DOM.
		for (const child of [...parent.childNodes]) {
			if (child.nodeType === Node.TEXT_NODE) {
				run.push(child);
				continue;
			}

			if (child.nodeType !== Node.ELEMENT_NODE) continue;

			if (excluded.has(child.tagName) || child.tagName === "BR") {
				flush();
				continue;
			}

			const boundary = blocks.has(child.tagName);
			if (boundary) flush();
			visit(child);
			if (boundary) flush();
		}
	}

	visit(this);
	flush();
}
```

