private Coroutine moveCoroutine;

public void moveToCenter()
{
    if (moveCoroutine != null)
        StopCoroutine(moveCoroutine);

    Vector3 targetPos = new Vector3(
        Storage.movePos.x * dir,
        Storage.movePos.y,
        Storage.movePos.z
    );

    Quaternion targetRotation = Quaternion.Euler(Storage.rot);

    moveCoroutine = StartCoroutine(Move(targetPos, targetRotation));
