private IEnumerator Move(Vector3 targetPos, Quaternion targetRotation)
{
    Vector3 startPos = transform.position;
    Quaternion startRotation = transform.rotation;
    float length = Vector3.Distance(startPos, targetPos);

    if (length == 0f)
    {
        transform.SetPositionAndRotation(targetPos, targetRotation);
        yield break;
    }

    if (speed <= 0f)
    {
        Debug.LogWarning("Movement speed must be positive.");
        yield break;
    }

    float elapsed = 0f;

    while (elapsed * speed < length)
    {
        float t = elapsed * speed / length;

        transform.position = Vector3.Lerp(startPos, targetPos, t);
        transform.rotation =
            Quaternion.Lerp(startRotation, targetRotation, t);

        yield return null;
        elapsed += Time.deltaTime;
    }

    transform.SetPositionAndRotation(targetPos, targetRotation);
}

private void stopAnimation()
{
    if (moveCoroutine != null)
    {
