Here’s a version that snapshots both endpoints, stops any previous movement, and finishes at the target:

```csharp
using System.Collections;
using UnityEngine;

public class moveCard : MonoBehaviour
{
    public storage Storage;
    public float speed = 20f;
    public int dir = 1;

    private Coroutine moveCoroutine;

    void Awake()
    {
        if (gameObject.name == "reference")
            Storage.movePos = transform.position;
    }

    public void moveToCenter()
    {
        if (speed <= 0f)
        {
            Debug.LogWarning("Movement speed must be positive.");
            return;
        }

        if (moveCoroutine != null)
            StopCoroutine(moveCoroutine);

        Vector3 endPos = new Vector3(
            Storage.movePos.x * dir,
            Storage.movePos.y,
            Storage.movePos.z
        );

        Quaternion endRotation = Quaternion.Euler(Storage.rot);

        moveCoroutine = StartCoroutine(Move(endPos, endRotation));
    }

    private IEnumerator Move(Vector3 endPos, Quaternion endRotation)
    {
        Vector3 startPos = transform.position;
        Quaternion startRotation = transform.rotation;

        float duration = Vector3.Distance(startPos, endPos) / speed;
        float elapsed = 0f;

        // A zero-length journey skips the loop and sets the final values.
        while (elapsed < duration)
        {
            float t = Mathf.Clamp01(elapsed / duration);

            transform.position = Vector3.Lerp(startPos, endPos, t);
            transform.rotation =
                Quaternion.Lerp(startRotation, endRotation, t);

            yield return null;
            elapsed += Time.deltaTime;
        }

        transform.position = endPos;
        transform.rotation = endRotation;
    }
}
```

This removes the timed stop so the movement can finish naturally.

