from textual.containers import Horizontal, VerticalScroll
from textual.widgets import Button, Static


class FileRow(Horizontal):
    can_focus = True
    BINDINGS = [("enter", "select_file", "Select file")]

    def __init__(self, filename: str) -> None:
        super().__init__()
        self.filename = filename

    def compose(self) -> ComposeResult:
        yield Static(self.filename, classes="filename", markup=False)
        yield Button("Delete", variant="error", classes="delete")

    def action_select_file(self) -> None:
        self.app.notify(f"Selected: {self.filename}")

    def on_click(self, event: events.Click) -> None:
        # Button handles and stops its own click events, so clicking
        # Delete doesn't also select this row.
        event.stop()
        self.action_select_file()

    async def on_button_pressed(self, event: Button.Pressed) -> None:
        if event.button.has_class("delete"):
            event.stop()
            await self.remove()
            self.app.notify(f"Removed from list: {self.filename}")


