## My answer to the user prompt

The important detail is to **reserve space for “See more.”** Appending it inside a truncated `<Text>` can cause the link itself to be truncated.

Below is a dependency-free TypeScript component. It measures an unrestricted, hidden copy of the text to detect overflow, then renders the collapsed text and button in a non-wrapping row.

### `ExpandableText.tsx`

```tsx
import React, { useState } from 'react';
import {
  Pressable,
  StyleSheet,
  Text,
  View,
  useWindowDimensions,
  type StyleProp,
  type TextStyle,
  type ViewStyle,
} from 'react-native';

export interface ExpandableTextProps {
  text: string;
  containerStyle?: StyleProp<ViewStyle>;
  /** Typography styles only; apply layout styles to containerStyle. */
  textStyle?: StyleProp<TextStyle>;
  seeMoreStyle?: StyleProp<TextStyle>;
  seeMoreText?: string;
  onExpand?: () => void;
}

interface ContentProps extends ExpandableTextProps {
  width: number;
}

function Content({
  text,
  width,
  textStyle,
  seeMoreStyle,
  seeMoreText = 'See more',
  onExpand,
}: ContentProps) {
  const [expanded, setExpanded] = useState(false);
  const [overflows, setOverflows] = useState(false);

  const typography = [styles.text, textStyle];
  const showButton = overflows && !expanded;

  return (
    <View style={{ width }}>
      {/* Measure the full text independently of the truncated display.
          Do not set height: 0 or numberOfLines on this copy. */}
      <View
        pointerEvents="none"
        accessible={false}
        accessibilityElementsHidden
        importantForAccessibility="no-hide-descendants"
        style={styles.measurement}
      >
        <Text
          accessible={false}
          style={typography}
          onTextLayout={({ nativeEvent }) => {
            const lines = nativeEvent.lines;

            setOverflows(
              lines.length > 1 ||
                lines.some(line => line.width > width + 0.5),
            );
          }}
        >
          {text}
        </Text>
      </View>

      <View style={styles.row}>
        <Text
          style={[typography, styles.visibleText]}
          numberOfLines={expanded ? undefined : 1}
          ellipsizeMode="tail"
        >
          {text}
        </Text>

        {showButton && (
          <Pressable
            accessibilityRole="button"
            accessibilityLabel={seeMoreText}
            accessibilityHint="Shows the full text"
            accessibilityState={{ expanded: false }}
            hitSlop={8}
            style={styles.button}
            onPress={() => {
              setExpanded(true);
              onExpand?.();
            }}
          >
            {({ pressed }) => (
              <Text
                style={[
                  typography,
                  styles.link,
                  seeMoreStyle,
                  pressed && styles.pressed,
                ]}
              >
                {seeMoreText}
              </Text>
            )}
          </Pressable>
        )}
      </View>
    </View>
  );
}

export default function ExpandableText(props: ExpandableTextProps) {
  const [width, setWidth] = useState(0);
  const { fontScale } = useWindowDimensions();

  // Remount the measurement/display state when its inputs change.
  // This also intentionally collapses the text after these changes.
  const measurementKey = JSON.stringify([
    props.text,
    width,
    fontScale,
    StyleSheet.flatten(props.textStyle),
  ]);

  return (
    <View style={props.containerStyle}>
      <View
        onLayout={({ nativeEvent }) => {
          setWidth(nativeEvent.layout.width);
        }}
      >
        {width > 0 ? (
          <Content key={measurementKey} {...props} width={width} />
        ) : (
          <Text
            style={[styles.text, props.textStyle]}
            numberOfLines={1}
            ellipsizeMode="tail"
          >
