Without this key, requesting microphone access can terminate the app.

### 2. Recording service

```swift
import AVFoundation
import Foundation

enum RecordingError: LocalizedError {
    case permissionDenied
    case couldNotStart
    case notRecording

    var errorDescription: String? {
        switch self {
        case .permissionDenied:
            return "Enable microphone access for this app in Settings."
        case .couldNotStart:
            return "The audio recording could not start."
        case .notRecording:
            return "There is no active recording."
        }
    }
}

@MainActor
protocol AudioRecordingService: AnyObject {
    func start() async throws
    func finish() throws -> URL
    func normalizedLevel() -> Float
}

@MainActor
final class AudioRecorderService: AudioRecordingService {
    private let session = AVAudioSession.sharedInstance()
    private var recorder: AVAudioRecorder?

    func start() async throws {
        guard recorder == nil else {
            throw RecordingError.couldNotStart
        }

        let granted = await AVAudioApplication.requestRecordPermission()
        try Task.checkCancellation()

        guard granted else {
            throw RecordingError.permissionDenied
        }

        let directory = try FileManager.default.url(
            for: .documentDirectory,
            in: .userDomainMask,
            appropriateFor: nil,
            create: true
        )
        let url = directory
            .appendingPathComponent(UUID().uuidString)
            .appendingPathExtension("m4a")

        do {
            try session.setCategory(.record, mode: .default)
            try session.setActive(true)

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100,
                AVNumberOfChannelsKey: 1,
                AVEncoderBitRateKey: 96_000,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let newRecorder = try AVAudioRecorder(
                url: url,
                settings: settings
            )
            newRecorder.isMeteringEnabled = true

            guard newRecorder.prepareToRecord(),
                  newRecorder.record() else {
                throw RecordingError.couldNotStart
            }

            recorder = newRecorder
        } catch {
            try? session.setActive(
                false,
                options: .notifyOthersOnDeactivation
            )
            try? FileManager.default.removeItem(at: url)
            throw error
        }
    }

    func finish() throws -> URL {
        guard let recorder else {
            throw RecordingError.notRecording
        }

        recorder.stop() // Finalizes the audio file.
        self.recorder = nil

        // Deactivation failure does not invalidate the saved recording.
        try? session.setActive(
            false,
            options: .notifyOthersOnDeactivation
        )

        return recorder.url
    }

    func normalizedLevel() -> Float {
        guard let recorder, recorder.isRecording else { return 0 }

        recorder.updateMeters()
        let db = recorder.averagePower(forChannel: 0)

        // A display mapping, not a frequency-spectrum measurement.
        return min(1, max(0, (db + 60) / 60))
    }
}
```

### 3. View model

Permission requests are asynchronous. Disable Start while permission/startup is pending, and cancel pending startup when the screen leaves.

```swift
import Combine
import Foundation

@MainActor
final class RecorderViewModel: ObservableObject {
    enum Phase {
        case idle
        case starting
        case recording
    }

    @Published private(set) var phase: Phase = .idle
    @Published private(set) var levels =
        Array(repeating: Float.zero, count: 16)
    @Published private(set) var savedURL: URL?
    @Published private(set) var errorMessage: String?

    private let service: any AudioRecordingService
    private var startTask: Task<Void, Never>?
    private var meterSubscription: AnyCancellable?

    init(service: any AudioRecordingService) {
        self.service = service
    }

    func start() {
        guard phase == .idle else { return }

        phase = .starting
        errorMessage = nil
        savedURL = nil
        levels = Array(repeating: 0, count: levels.count)

        startTask = Task { [weak self] in
            guard let self else { return }
            defer { startTask = nil }

            do {
                try await service.start()
                phase = .recording
                beginMetering()
            } catch is CancellationError {
                phase = .idle
            } catch {
                errorMessage = error.localizedDescription
                phase = .idle
            }
        }
    }

    func stop() {
        guard phase == .recording else { return }

        meterSubscription?.cancel()
        meterSubscription = nil

        do {
            savedURL = try service.finish()
        } catch {
            errorMessage = error.localizedDescription
        }

        levels = Array(repeating: 0, count: levels.count)
        phase = .idle
    }

    func leaveScreen() {
        startTask?.cancel()
        stop()
    }

    private func beginMetering() {
        meterSubscription = Timer
            .publish(every: 0.08, on: .main, in: .common)
            .autoconnect()
            .sink { [weak self] _ in
                Task { @MainActor [weak self] in
                    guard let self, phase == .recording else { return }
                    levels.removeFirst()
                    levels.append(service.normalizedLevel())
                }
            }
    }
}
```

