```swift
import AVFoundation
import Foundation

@MainActor
protocol RecordingService: AnyObject {
    func start() async throws
    func stop() -> URL?
    func level() -> CGFloat
}

enum RecordingError: LocalizedError {
    case permissionDenied
    case couldNotStart

    var errorDescription: String? {
        switch self {
        case .permissionDenied:
            return "Microphone access is disabled. Enable it in Settings."
        case .couldNotStart:
            return "The recording could not be started."
        }
    }
}

@MainActor
final class AudioRecordingService: RecordingService {
    private let session = AVAudioSession.sharedInstance()
    private var recorder: AVAudioRecorder?

    func start() async throws {
        guard recorder == nil else { return }

        let allowed = await AVAudioApplication.requestRecordPermission()
        try Task.checkCancellation()

        guard allowed else {
            throw RecordingError.permissionDenied
        }

        let directory = try FileManager.default.url(
            for: .documentDirectory,
            in: .userDomainMask,
            appropriateFor: nil,
            create: true
        )
        let url = directory
            .appendingPathComponent(UUID().uuidString)
            .appendingPathExtension("m4a")

        do {
            try session.setCategory(.record, mode: .default)
            try session.setActive(true)

            let recorder = try AVAudioRecorder(
                url: url,
                settings: [
                    AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                    AVSampleRateKey: 44_100,
                    AVNumberOfChannelsKey: 1,
                    AVEncoderBitRateKey: 96_000,
                    AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
                ]
            )
            recorder.isMeteringEnabled = true

            guard recorder.prepareToRecord(), recorder.record() else {
                throw RecordingError.couldNotStart
            }

            self.recorder = recorder
        } catch {
            try? session.setActive(
                false,
                options: .notifyOthersOnDeactivation
            )
            try? FileManager.default.removeItem(at: url)
            throw error
        }
    }

    func stop() -> URL? {
        guard let recorder else { return nil }

        recorder.stop()
        let url = recorder.url
        self.recorder = nil

        try? session.setActive(
            false,
            options: .notifyOthersOnDeactivation
        )

        return url
    }

    func level() -> CGFloat {
        guard let recorder, recorder.isRecording else { return 0 }

        recorder.updateMeters()
        let decibels = recorder.averagePower(forChannel: 0)

        // Map a practical speech display range of -60...0 dB to 0...1.
        return CGFloat(min(1, max(0, (decibels + 60) / 60)))
    }
}
```

### 3. View model

Permission requests are asynchronous. A preparing state prevents repeated Start taps, and cancellation prevents recording from starting after the user leaves the screen.

```swift
import Combine
import Foundation

@MainActor
final class RecorderViewModel: ObservableObject {
    enum State {
        case idle
        case preparing
        case recording
    }

    @Published private(set) var state: State = .idle
    @Published private(set) var levels: [CGFloat] =
        Array(repeating: 0, count: 15)
    @Published private(set) var savedURL: URL?
    @Published private(set) var errorMessage: String?

    private let service: any RecordingService
    private var work: Task<Void, Never>?
    private var generation = UUID()

    init(service: any RecordingService) {
        self.service = service
    }

    func start() {
        guard state == .idle else { return }

        state = .preparing
        errorMessage = nil
        levels = Array(repeating: 0, count: 15)

        let token = UUID()
        generation = token

        work = Task { [weak self] in
            guard let self else { return }

            do {
                try await service.start()
                try Task.checkCancellation()
                guard generation == token else { return }

                state = .recording

                while !Task.isCancelled {
                    levels.removeFirst()
                    levels.append(service.level())
                    try await Task.sleep(for: .milliseconds(80))
                }
            } catch is CancellationError {
                // stop() owns cancellation cleanup.
            } catch {
                guard generation == token else { return }

                _ = service.stop()
                state = .idle
                errorMessage = error.localizedDescription
                work = nil
            }
        }
    }

    func stop() {
        generation = UUID()
        work?.cancel()
        work = nil

        if let url = service.stop() {
            savedURL = url
        }

        state = .idle
        levels = Array(repeating: 0, count: 15)
    }
}
```

