  --keyword:#c6a2ff;--string:#9bdda6;--number:#ffca87;--comment:#8fa2b7
}
body.light{
  --bg:#fff;--panel:#edf1f7;--text:#243047;--edge:#b7c3d5;
  --keyword:#7334ac;--string:#237339;--number:#975300;--comment:#637083
}
body{
  margin:0;height:100dvh;display:flex;flex-direction:column;
  background:var(--bg);color:var(--text);font:14px system-ui
}
header,footer,#search{
  padding:10px;display:flex;gap:7px;align-items:center;flex-wrap:wrap;
  background:var(--panel)
}
button,input,select{
  font:inherit;color:inherit;background:var(--bg);
  border:1px solid var(--edge);border-radius:6px;padding:6px
}
button{cursor:pointer}
button:hover{filter:brightness(1.15)}
button:focus-visible,input:focus-visible,select:focus-visible{
  outline:2px solid #72adff;outline-offset:2px
}
#name{width:160px}
#search[hidden]{display:none}
main{display:flex;flex:1;min-height:0}
#gutter{
  flex:none;min-width:46px;margin:0;padding:12px 8px;
  text-align:right;background:var(--panel);overflow:hidden;
  color:var(--comment);user-select:none
}
#surface{position:relative;flex:1;min-width:0}
#gutter,#paint,#editor{font:var(--size,14px)/1.6 monospace}
#paint,#editor{
  position:absolute;inset:0;width:100%;height:100%;margin:0;
  border:0;padding:12px;tab-size:2;white-space:pre;
  overflow:auto;overflow-wrap:normal
}
#paint{pointer-events:none}
#editor{
  resize:none;outline:none;background:transparent;color:transparent;
  caret-color:var(--text)
}
#editor::selection{background:#6399de66;color:transparent}
body.wrap #paint,body.wrap #editor{
  white-space:pre-wrap;overflow-wrap:anywhere
}
body.wrap #gutter{display:none}
.kw{color:var(--keyword)}
.str{color:var(--string)}
.num{color:var(--number)}
.com{color:var(--comment)}
footer{justify-content:space-between;font-size:12px}
#message{color:var(--comment)}
</style>
</head>
<body>
<header aria-label="Editor tools">
<strong>Pocket Codepad</strong>
<input id="name" value="untitled.js" aria-label="Filename">
<button id="new">New</button>
<button id="open">Open</button>
<button id="download">Download</button>
<select id="language" aria-label="Language">
  <option value="js">JavaScript</option>
  <option value="json">JSON</option>
  <option value="python">Python</option>
  <option value="markup">HTML / XML</option>
  <option value="css">CSS</option>
  <option value="text">Plain text</option>
</select>
<button id="findButton">Find / Replace</button>
<button id="theme">Light / Dark</button>
<button id="wrap" aria-pressed="false">Wrap</button>
<button id="smaller" aria-label="Decrease font size">A−</button>
<button id="larger" aria-label="Increase font size">A+</button>
<button id="goto">Go to line</button>
</header>

<section id="search" hidden aria-label="Find and replace">
<input id="query" aria-label="Find text" placeholder="Find text">
<input id="replacement" aria-label="Replacement" placeholder="Replace with">
<label><input type="checkbox" id="caseSensitive" checked>Match case</label>
<button id="next">Next</button>
<button id="replaceOne">Replace</button>
<button id="replaceAll">Replace all</button>
<button id="closeSearch">Close</button>
</section>

<main>
<pre id="gutter" aria-hidden="true"></pre>
<div id="surface">
<pre id="paint" aria-hidden="true"></pre>
<textarea id="editor" aria-label="Document editor"
  spellcheck="false" autocapitalize="off" autocomplete="off"
  wrap="off"></textarea>
</div>
</main>

<footer>
<span id="stats"></span>
<span id="message" role="status">Ready</span>
<span>Ctrl/⌘ S: download · Ctrl/⌘ F: find · Esc: close search</span>
</footer>
<input type="file" id="file" hidden>

<script>
'use strict';
const $ = id => document.getElementById(id);
const editor = $('editor'), paint = $('paint'), gutter = $('gutter');
let size = 14, timer;
const storageKey = 'pocket-codepad-v1';

function message(text) { $('message').textContent = text; }
function escapeHTML(text) {
  return text.replace(/[&<>]/g, c =>
    ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
}

/* Each source token is processed once; generated spans are never re-tokenized. */
const patterns = {
  js: /(?<com>\/\/[^\n]*|\/\*[\s\S]*?\*\/)|(?<str>"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`)|(?<kw>\b(?:const|let|var|function|return|if|else|for|while|class|new|async|await|import|export|true|false|null|try|catch|throw)\b)|(?<num>\b\d+(?:\.\d+)?\b)/g,
  python: /(?<com>#[^\n]*)|(?<str>"""[\s\S]*?"""|'''[\s\S]*?'''|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')|(?<kw>\b(?:def|class|return|if|elif|else|for|while|in|is|not|and|or|import|from|as|True|False|None|try|except|with|lambda)\b)|(?<num>\b\d+(?:\.\d+)?\b)/g,
  json: /(?<str>"(?:\\.|[^"\\])*")|(?<kw>\b(?:true|false|null)\b)|(?<num>-?\b\d+(?:\.\d+)?(?:[eE][+-]?\d+)?\b)/g,
  markup: /(?<com><!--[\s\S]*?-->)|(?<str>"[^"]*"|'[^']*')|(?<kw><\/?[\w:-]+|\/?>)/g,
  css: /(?<com>\/\*[\s\S]*?\*\/)|(?<str>"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')|(?<kw>[\w-]+(?=\s*:))|(?<num>#[\da-fA-F]{3,8}\b|\b\d+(?:\.\d+)?(?:px|rem|em|vh|vw|%)?)/g
};

function highlight(source) {
  const re = patterns[$('language').value];
  if (!re) return escapeHTML(source);
  re.lastIndex = 0;
  let result = '', last = 0;
  for (const match of source.matchAll(re)) {
    const type = Object.keys(match.groups).find(k =>
      match.groups[k] !== undefined);
    result += escapeHTML(source.slice(last, match.index));
    result += '<span class="' + type + '">' +
      escapeHTML(match[0]) + '</span>';
    last = match.index + match[0].length;
  }
  return result + escapeHTML(source.slice(last));
}

function syncScroll() {
  paint.scrollTop = editor.scrollTop;
  paint.scrollLeft = editor.scrollLeft;
  gutter.scrollTop = editor.scrollTop;
}

function updateStats() {
  const text = editor.value, position = editor.selectionStart;
  const before = text.slice(0, position);
  $('stats').textContent =
    `Ln ${before.split('\n').length}, Col ${position - before.lastIndexOf('\n')}` +
    ` · ${text.split('\n').length} lines` +
    ` · ${(text.match(/\S+/g) || []).length} words · ${text.length} characters`;
}

function render() {
  paint.innerHTML = highlight(editor.value) + '\n';
  gutter.textContent = Array.from(
    {length: editor.value.split('\n').length}, (_, i) => i + 1
  ).join('\n');
  /* Match the textarea's content viewport, including scrollbar space. */
  paint.style.width = editor.clientWidth + 'px';
  paint.style.height = editor.clientHeight + 'px';
  updateStats();
  syncScroll();
}

function persist() {
  clearTimeout(timer);
  try {
    localStorage.setItem(storageKey, JSON.stringify({
      text: editor.value, name: $('name').value,
      language: $('language').value,
      light: document.body.classList.contains('light'),
      wrap: document.body.classList.contains('wrap'), size
    }));
    message('Saved in this browser');
  } catch {
    message('Browser storage unavailable or full—download a backup.');
  }
}
function changed() {
  render();
  message('Saving…');
  clearTimeout(timer);
  timer = setTimeout(persist, 400);
}
editor.addEventListener('input', changed);
editor.addEventListener('scroll', syncScroll);
editor.addEventListener('click', updateStats);
editor.addEventListener('keyup', updateStats);
$('language').onchange = changed;
$('name').oninput = changed;

function edit(text, start = editor.selectionStart, end = editor.selectionEnd) {
  editor.setRangeText(text, start, end, 'end');
  changed();
  editor.focus();
}

editor.addEventListener('keydown', event => {
  if (event.key === 'Tab') {
    event.preventDefault();
    if (!event.shiftKey) edit('  ');
    else {
      const p = editor.selectionStart;
      const start = editor.value.lastIndexOf('\n', p - 1) + 1;
      const spaces = editor.value.slice(start).match(/^ {1,2}/);
      if (spaces) edit('', start, start + spaces[0].length);
    }
  } else if (event.key === 'Enter') {
    event.preventDefault();
    const p = editor.selectionStart;
    const start = editor.value.lastIndexOf('\n', p - 1) + 1;
    const line = editor.value.slice(start, p);
    const indent = line.match(/^[ \t]*/)[0];
    edit('\n' + indent + (/[{[(：:]$/.test(line) ? '  ' : ''));
  }
});

function download() {
  const url = URL.createObjectURL(new Blob(
    [editor.value], {type:'text/plain;charset=utf-8'}
  ));
  const link = document.createElement('a');
  link.href = url;
  link.download = $('name').value.trim() || 'note.txt';
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  persist();
}
$('download').onclick = download;
$('new').onclick = () => {
  if (editor.value && !confirm('Clear this document? Download a backup first.')) return;
  editor.value = '';
  $('name').value = 'untitled.txt';
  $('language').value = 'text';
  changed();
  editor.focus();
};
$('open').onclick = () => $('file').click();
$('file').onchange = async event => {
  const file = event.target.files[0];
  event.target.value = '';
  if (!file) return;
  if (editor.value && !confirm('Replace the current document?')) return;
  try {
    const text = await file.text();
    editor.value = text;
    $('name').value = file.name;
    const extension = file.name.split('.').pop().toLowerCase();
    $('language').value = ({
      js:'js',mjs:'js',json:'json',py:'python',
      html:'markup',xml:'markup',css:'css'
    })[extension] || 'text';
    changed();
  } catch { message('Could not read that file.'); }
};

function openSearch() {
  $('search').hidden = false;
  $('query').focus();
}
function searchRegex() {
  const query = $('query').value;
  if (!query) return null;
  return new RegExp(
    query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'),
    $('caseSensitive').checked ? 'g' : 'gi'
  );
}
function next() {
  const re = searchRegex();
  if (!re) return;
  re.lastIndex = editor.selectionEnd;
  let match = re.exec(editor.value);
  if (!match) { re.lastIndex = 0; match = re.exec(editor.value); }
  if (!match) { message('No matches'); return; }
  editor.focus();
  editor.setSelectionRange(match.index, match.index + match[0].length);
  const line = editor.value.slice(0, match.index).split('\n').length - 1;
  editor.scrollTop = line * parseFloat(getComputedStyle(editor).lineHeight);
  syncScroll();
  updateStats();
}
$('findButton').onclick = openSearch;
$('next').onclick = next;
$('replaceOne').onclick = () => {
  const re = searchRegex();
  if (!re) return;
  const selected = editor.value.slice(editor.selectionStart, editor.selectionEnd);
  const match = re.exec(selected);
  if (match && match.index === 0 && match[0].length === selected.length)
    edit($('replacement').value);
  next();
};
$('replaceAll').onclick = () => {
  const re = searchRegex();
  if (!re) return;
  let count = 0;
  editor.value = editor.value.replace(re, () => {
    count++;
    return $('replacement').value;
  });
  changed();
  message(`Replaced ${count} matches`);
};
$('query').onkeydown = event => {
  if (event.key === 'Enter') { event.preventDefault(); next(); }
};
$('closeSearch').onclick = () => {
  $('search').hidden = true;
  editor.focus();
};
$('theme').onclick = () => { document.body.classList.toggle('light'); persist(); };
$('wrap').onclick = () => {
  const enabled = document.body.classList.toggle('wrap');
  $('wrap').setAttribute('aria-pressed', enabled);
  render(); persist();
};
function zoom(delta) {
  size = Math.max(10, Math.min(30, size + delta));
  document.body.style.setProperty('--size', size + 'px');
  render(); persist();
}
$('smaller').onclick = () => zoom(-1);
$('larger').onclick = () => zoom(1);
$('goto').onclick = () => {
  const number = Number(prompt('Line number:'));
  if (!Number.isInteger(number) || number < 1) return;
  const lines = editor.value.split('\n');
  const target = Math.min(number, lines.length) - 1;
  const position = lines.slice(0, target).reduce((sum, line) => sum + line.length + 1, 0);
  editor.focus();
  editor.setSelectionRange(position, position);
  editor.scrollTop = target * parseFloat(getComputedStyle(editor).lineHeight);
  syncScroll(); updateStats();
};
document.addEventListener('keydown', event => {
  const mod = event.ctrlKey || event.metaKey;
  if (mod && event.key.toLowerCase() === 's') {
    event.preventDefault(); download();
  }
  if (mod && event.key.toLowerCase() === 'f') {
    event.preventDefault(); openSearch();
  }
  if (event.key === 'Escape') $('closeSearch').click();
});
try {
  const saved = JSON.parse(localStorage.getItem(storageKey) || 'null');
  if (saved && typeof saved.text === 'string') {
    editor.value = saved.text;
    $('name').value = saved.name || 'note.txt';
    $('language').value = saved.language || 'text';
    document.body.classList.toggle('light', !!saved.light);
    document.body.classList.toggle('wrap', !!saved.wrap);
    $('wrap').setAttribute('aria-pressed', !!saved.wrap);
    size = Math.max(10, Math.min(30, Number(saved.size) || 14));
    document.body.style.setProperty('--size', size + 'px');
  }
} catch { message('Could not restore browser autosave.'); }
new ResizeObserver(render).observe($('surface'));
window.addEventListener('pagehide', persist);
render();
</script>
</body>
</html>
```

Browser autosave is not a permanent backup; download important documents. Native undo works for ordinary typing, but programmatic editing commands would need a dedicated history system for full editor-grade undo support.

## Evaluation

The prompt is broad but actionable. Neither assistant needed clarification before choosing a design. Both attempted a self-contained, dependency-free implementation, which matches the request. However, working features matter more than advertised feature counts.

### Assistant A

**Strengths**
- Provides a complete single-file implementation.
- Includes useful basics: open/save, language selection, themes, find/replace, statistics, and autosave.
- Appropriately describes its highlighting as rudimentary.

**Important defects**
- **The highlighting algorithm corrupts its own generated markup.** After inserting comment spans, the string pass matches their quoted `class` attributes. The keyword pass also matches `class` inside generated tags. The correction is to tokenize the original source once and escape each token before adding markup, as in my answer.
- **The overlay is incorrectly styled.** The textarea has opaque text (`color: inherit`) above the highlighted layer. Its background is transparent, but its text is not, so colored and ordinary glyphs overlap. The textarea needs transparent text and a visible caret.
- **The editor does not fill the available editing area.** It has no height or auto-growing implementation, defaults to a small textarea, and explicitly disables resizing despite the introduction calling it resizable.
- **Scrolling and line numbers are unreliable.** Scrolling is handled on the textarea even though the wrapper is also a scroll container; gutter typography does not match the editor, and wrapped lines are not accounted for.
- **Replace All unexpectedly interprets input as a regular expression.** Ordinary searches containing `[` can throw; `.` replaces every character. Literal search should escape metacharacters or use an explicitly labeled regex mode.
- Storage access is unguarded, and downloads always use `note.txt`.

A therefore offers some usable notepad functionality, but its central syntax-highlighting feature needs substantial correction.

### Assistant B

**Strengths**
- Much more ambitious feature coverage and a more polished visual design.
- Better intended architecture for highlighting: tokenizing source rather than repeatedly modifying generated HTML.
- Includes thoughtful extras such as language detection, shortcuts documentation, themes, tabs, and debounced persistence.

**Critical defects**
- **The script cannot parse as written.** Markdown patterns contain unescaped backticks inside backtick-delimited `String.raw` template literals, including the fenced-code pattern beginning with `String.raw` followed by a backtick and `^` plus triple backticks. `String.raw` does not change JavaScript’s delimiter rules. This prevents the entire script from executing—not just Markdown highlighting. These patterns must use safely quoted strings or correctly escaped delimiters.
- **Even after that fix, rendering collapses the workspace.** `lnEl.parentElement` is `<main>`, so assigning its width sets the entire editor workspace to only a few character widths. Gutter scrolling also targets `<main>` rather than the gutter. Additionally, gutter newlines need preserved whitespace.
- **Tab handling can destroy content.** Closing the active tab assigns the replacement active ID before calling `switchTab`, causing the closing document’s textarea content to overwrite the surviving document. Restoration similarly writes the initially empty textarea into the restored active file before reading it.
- **Several advertised editing features are broken.** Find Next repeatedly selects the same match; Duplicate Line omits the newline; bracket wrapping discards selected text; and bracket matching has both traversal and rendering errors.
- **Markdown preview is unsafe for untrusted files.** Escaping `<`, `>`, and `&` does not safely encode text inserted into quoted HTML attributes. Link/image values also require URL validation. DOM construction and sanitization would be preferable.
- Storage failures are silently caught while the interface still reports successful saving.

These are not minor limitations: as delivered, B has no functioning JavaScript, and fixing that alone exposes major layout and data-loss bugs.

### Overall comparison

B is more creative and comprehensive on paper, but its claims greatly exceed its implementation. A is less polished and also substantially flawed, yet its script can execute and provide basic editing, file operations, and persistence.

Both would benefit from browser testing, reliable undo/redo for custom operations, accessible editor controls, robust storage-error handling, and explicit limitations. B’s longer feature table adds little value when the underlying features do not work.

**My final verdict is Assistant A is significantly better: [[A>>B]]**

## My answer to the user prompt

Save the following as **`notepad.html`** and open it in a modern browser. It is self-contained and works without external libraries.

Features include lightweight syntax highlighting, line numbers, multiple named notes, browser autosave, file import/export, literal find and replace, indentation, font sizing, themes, focus mode, and document statistics. Highlighting is intentionally lightweight rather than a full language parser. Export important notes—browser storage is not a backup.

