<script>
const $ = id => document.getElementById(id);
const edit = $('edit'), paint = $('paint');
const key = 'pocket-studio-v1';
let state = {
  index:0, light:false, size:15,
  notes:[{name:'Welcome.js',lang:'js',
    text:'// Welcome! Your notes stay in this browser.\nconst greeting = "Hello";\n'}]
};
try {
  const data = JSON.parse(localStorage.getItem(key));
  if (data && Array.isArray(data.notes) && data.notes.length &&
      data.notes.every(n => typeof n.name === 'string' &&
        typeof n.text === 'string' && typeof n.lang === 'string') &&
      Number.isInteger(data.index) && data.notes[data.index]) {
    state = data;
  }
} catch {}
state.size = Math.max(10, Math.min(30, Number(state.size) || 15));

const escapeHTML = s => s.replace(/[&<>]/g,
  c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const keywords = new Set(
  ('const let var function return if else for while class new async await ' +
   'import export from true false null undefined def elif in is not and or ' +
   'True False None try catch except finally throw raise with as pass').split(' ')
);
function highlight(text, lang) {
  if (lang === 'text') return escapeHTML(text);
  // Tokenize original text once; never tokenize generated HTML.
  const rx = lang === 'py'
    ? /#[^\n]*|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b\d+(?:\.\d+)?\b|\b[A-Za-z_]\w*\b/g
    : /\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b\d+(?:\.\d+)?\b|\b[A-Za-z_]\w*\b/g;
  let out = '', end = 0;
  for (const m of text.matchAll(rx)) {
    out += escapeHTML(text.slice(end, m.index));
    const t = m[0];
    const type = /^(#|\/\/|\/\*)/.test(t) ? 'comment'
      : /^["']/.test(t) ? 'string'
      : /^\d/.test(t) ? 'number'
      : keywords.has(t) ? 'keyword' : '';
    out += type ? '<span class="' + type + '">' +
      escapeHTML(t) + '</span>' : escapeHTML(t);
    end = m.index + t.length;
  }
  return out + escapeHTML(text.slice(end));
}
function capture() {
  state.notes[state.index].text = edit.value;
}
