    [SerializeField] private float moveSpeed = 4f;
    [SerializeField] private float probeDistance = 1.5f;
    [SerializeField] private float alignmentSpeed = 12f;

    // An inward speed, not a gravitational acceleration.
    [SerializeField] private float adhesionSpeed = 2f;

    private Rigidbody body;
    private Vector2 input;

    private void Awake()
    {
        body = GetComponent<Rigidbody>();
        body.useGravity = false;
        body.freezeRotation = true;
        body.interpolation = RigidbodyInterpolation.Interpolate;
        body.collisionDetectionMode = CollisionDetectionMode.ContinuousDynamic;
    }

    private void Update()
    {
        input = Vector2.ClampMagnitude(new Vector2(
            Input.GetAxisRaw("Horizontal"),
            Input.GetAxisRaw("Vertical")), 1f);
    }

    private void FixedUpdate()
    {
        Vector3 up = body.rotation * Vector3.up;

        if (!Physics.Raycast(
            body.position, -up, out RaycastHit hit,
            probeDistance, surfaceMask,
            QueryTriggerInteraction.Ignore))
        {
            // Deliberately stop when tracking is lost.
            // Replace this with falling or surface reacquisition if desired.
            body.velocity = Vector3.zero;
            return;
        }

        Vector3 normal = hit.normal;

        Quaternion targetRotation =
            Quaternion.FromToRotation(up, normal) * body.rotation;

        float blend =
            1f - Mathf.Exp(-alignmentSpeed * Time.fixedDeltaTime);

        body.MoveRotation(
            Quaternion.Slerp(body.rotation, targetRotation, blend));

        Vector3 forward = Vector3.ProjectOnPlane(
            body.rotation * Vector3.forward, normal);

        // Avoid a degenerate tangent when encountering a sudden normal change.
        if (forward.sqrMagnitude < 0.0001f)
        {
            forward = Vector3.ProjectOnPlane(
                body.rotation * Vector3.right, normal);
        }

        forward.Normalize();
        Vector3 right = Vector3.Cross(normal, forward).normalized;

        Vector3 tangentVelocity =
            (right * input.x + forward * input.y) * moveSpeed;

        // The collider prevents penetration; this velocity maintains contact.
        body.velocity = tangentVelocity - normal * adhesionSpeed;
    }
}
```

