Do you mean **moving each quad along its normal**, or **giving it thickness, producing a box**? Also, which Unity render pipeline and target platform are you using?

Below assumes **solid extrusion along local +Z**, using Unity’s **Built-in Render Pipeline**. It emits one box per nontransparent texel. Geometry shaders require a supported graphics API; they are not supported by Metal.

A geometry shader runs per input primitive, not per texture pixel, so a small script supplies **one point per texel**.

### Shader

This uses explicit mip-level sampling because implicit-derivative texture sampling is not available in a geometry shader. The output is unlit and alpha-tested, not partially transparent.

```hlsl
Shader "Custom/ExtrudedTexels"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _PixelSize ("Pixel size (local units)", Float) = 0.01
        _Extrude ("Thickness (local units)", Float) = 0.1
        _AlphaCutoff ("Alpha cutoff", Range(0, 1)) = 0
    }

    SubShader
    {
        Tags { "RenderType"="Opaque" }
        Cull Off
        ZWrite On

        Pass
        {
            CGPROGRAM
            #pragma target 4.0
            #pragma vertex Vert
            #pragma geometry Geom
            #pragma fragment Frag
            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _PixelSize;
            float _Extrude;
            float _AlphaCutoff;

            struct Attributes
            {
                float4 position : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct VertexOutput
            {
                float4 position : SV_POSITION;
                float3 localPosition : TEXCOORD0;
                float2 uv : TEXCOORD1;
            };

            struct GeometryOutput
            {
                float4 position : SV_POSITION;
                float4 color : COLOR0;
            };

            VertexOutput Vert(Attributes v)
            {
                VertexOutput o;
                o.position = UnityObjectToClipPos(v.position);
                o.localPosition = v.position.xyz;
                o.uv = v.uv;
                return o;
            }

            // a,b,c,d are in triangle-strip order.
            void EmitFace(
                float3 a, float3 b, float3 c, float3 d,
                float4 color,
                inout TriangleStream<GeometryOutput> stream)
            {
                GeometryOutput o;
                o.color = color;

                o.position = UnityObjectToClipPos(float4(a, 1));
                stream.Append(o);
                o.position = UnityObjectToClipPos(float4(b, 1));
                stream.Append(o);
                o.position = UnityObjectToClipPos(float4(c, 1));
                stream.Append(o);
                o.position = UnityObjectToClipPos(float4(d, 1));
                stream.Append(o);

                stream.RestartStrip();
            }

            [maxvertexcount(24)]
            void Geom(
                point VertexOutput input[1],
                inout TriangleStream<GeometryOutput> stream)
            {
                float4 color =
                    tex2Dlod(_MainTex, float4(input[0].uv, 0, 0));

                // At cutoff 0, every texel with alpha > 0 is included.
                if (color.a <= _AlphaCutoff)
                    return;

                color.a = 1;

                float3 p = input[0].localPosition;
                float h = 0.5 * _PixelSize;
                float3 extrusion = float3(0, 0, _Extrude);

                float3 p0 = p + float3(-h, -h, 0);
                float3 p1 = p + float3( h, -h, 0);
                float3 p2 = p + float3( h,  h, 0);
                float3 p3 = p + float3(-h,  h, 0);

                float3 p4 = p0 + extrusion;
                float3 p5 = p1 + extrusion;
                float3 p6 = p2 + extrusion;
                float3 p7 = p3 + extrusion;

                EmitFace(p1, p0, p2, p3, color, stream); // base
                EmitFace(p4, p5, p7, p6, color, stream); // cap
                EmitFace(p0, p4, p3, p7, color, stream); // left
                EmitFace(p5, p1, p6, p2, color, stream); // right
                EmitFace(p0, p1, p4, p5, color, stream); // bottom
                EmitFace(p3, p7, p2, p6, color, stream); // top
            }

            fixed4 Frag(GeometryOutput i) : SV_Target
            {
                return i.color;
            }
            ENDCG
        }
    }
}
```

### Point-mesh generator

Attach this to a GameObject and assign the texture and a material using the shader above.

```csharp
using UnityEngine;
using UnityEngine.Rendering;

[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class ExtrudedTexelMesh : MonoBehaviour
{
    public Texture2D texture;
    public Material sourceMaterial;

    [Min(0.0001f)] public float pixelSize = 0.01f;
    [Min(0f)] public float thickness = 0.1f;
    [Range(0f, 1f)] public float alphaCutoff = 0f;

    Mesh mesh;
    Material instanceMaterial;

    void Start()
    {
        if (!texture || !sourceMaterial)
        {
            Debug.LogError("Assign a texture and material.", this);
            return;
        }

        int width = texture.width;
        int height = texture.height;
        int count = checked(width * height);

        var vertices = new Vector3[count];
        var uvs = new Vector2[count];
        var indices = new int[count];

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                int i = y * width + x;

                vertices[i] = new Vector3(
                    (x + 0.5f - width * 0.5f) * pixelSize,
                    (y + 0.5f - height * 0.5f) * pixelSize,
                    0f);

                uvs[i] = new Vector2(
                    (x + 0.5f) / width,
                    (y + 0.5f) / height);

                indices[i] = i;
            }
        }

        mesh = new Mesh
        {
            name = "Texel Points",
            indexFormat = count > 65535
                ? IndexFormat.UInt32
                : IndexFormat.UInt16
        };

        mesh.vertices = vertices;
        mesh.uv = uvs;
        mesh.SetIndices(indices, MeshTopology.Points, 0);

        // CPU culling cannot see geometry generated by the shader.
        mesh.bounds = new Bounds(
            new Vector3(0f, 0f, thickness * 0.5f),
            new Vector3(
                width * pixelSize,
                height * pixelSize,
                Mathf.Max(thickness, 0.001f)));

        instanceMaterial = new Material(sourceMaterial);
        instanceMaterial.SetTexture("_MainTex", texture);
        instanceMaterial.SetFloat("_PixelSize", pixelSize);
        instanceMaterial.SetFloat("_Extrude", thickness);
        instanceMaterial.SetFloat("_AlphaCutoff", alphaCutoff);

        GetComponent<MeshFilter>().sharedMesh = mesh;
        GetComponent<MeshRenderer>().sharedMaterial = instanceMaterial;
    }

    void OnDestroy()
    {
        if (mesh) Destroy(mesh);
        if (instanceMaterial) Destroy(instanceMaterial);
    }
}
```

Use **Point filtering** for pixel-art behavior. Texture Read/Write access is unnecessary because the CPU does not read texel colors. Sizes are in **object-local units**, so the GameObject’s scale affects them.

This initialization-only example requires updating the mesh bounds if thickness changes later. It also emits internal faces between neighboring boxes; large textures can become expensive.

