## My answer to the prompt

Use a single table inside a height-constrained scrolling container, with sticky header cells. After **every fetch**, check whether the container is full; if not, fetch another page. This avoids getting stuck when the first page is too short to produce a scrollbar.

The example below assumes:

- `start` is a zero-based offset.
- The API returns `{ rows: [...], total?: number }`.
- Without `total`, a page shorter than `count` indicates the end.
- Rows have a unique `id`, and the API uses a stable ordering.

### 1. Register Pinia

```js
// main.js
import { createApp } from 'vue'
import { createPinia } from 'pinia'
import App from './App.vue'

createApp(App).use(createPinia()).mount('#app')
```

### 2. Fetch rows in the store

```js
// stores/rows.js
import { defineStore } from 'pinia'

export const useRowsStore = defineStore('rows', {
  state: () => ({
    rows: [],
    loading: false,
    hasMore: true,
    error: null,
  }),

  actions: {
    async fetchNext(count = 50) {
      if (this.loading || !this.hasMore) return false

      this.loading = true
      this.error = null

      try {
        const start = this.rows.length
        const params = new URLSearchParams({
          start: String(start),
          count: String(count),
        })

        const response = await fetch(`/api/rows?${params}`)
        if (!response.ok) {
          throw new Error(`Request failed: ${response.status}`)
        }

        const data = await response.json()
        if (!Array.isArray(data.rows)) {
          throw new Error('Expected a rows array')
        }

        this.rows.push(...data.rows)

        // An empty page must stop loading, even if total is inconsistent.
        this.hasMore =
          data.rows.length > 0 &&
          (typeof data.total === 'number'
            ? this.rows.length < data.total
            : data.rows.length === count)

        return true
      } catch (error) {
        this.error = error.message || 'Unable to load rows'
        return false
      } finally {
        this.loading = false
      }
    },
  },
})
```

### 3. Infinite-scrolling table

```vue
<!-- components/InfiniteTable.vue -->
<script setup>
import { ref, nextTick, onMounted, onBeforeUnmount } from 'vue'
import { useRowsStore } from '../stores/rows'

const store = useRowsStore()
const container = ref(null)

const pageSize = 50
const threshold = 150

let checking = false
let stopped = false
let resizeObserver

function needsMoreRows() {
  const el = container.value
  return (
    el &&
    el.clientHeight > 0 &&
    el.scrollHeight - el.scrollTop - el.clientHeight <= threshold
  )
}

async function fillAvailableSpace() {
  if (checking || stopped || store.error) return
  checking = true

  try {
    // Check actual rendered height, not an estimated row height.
    await nextTick()

    while (
      !stopped &&
      store.hasMore &&
      !store.error &&
      needsMoreRows()
    ) {
      const loaded = await store.fetchNext(pageSize)
      if (!loaded) break

      await nextTick()
    }
  } finally {
    checking = false
  }
}

function retry() {
  store.error = null
  void fillAvailableSpace()
}

onMounted(() => {
  resizeObserver = new ResizeObserver(() => {
    void fillAvailableSpace()
  })
  resizeObserver.observe(container.value)

  void fillAvailableSpace()
})

onBeforeUnmount(() => {
  stopped = true
  resizeObserver?.disconnect()
})
</script>

<template>
  <div
    ref="container"
    class="table-scroll"
    role="region"
    aria-label="Records"
    tabindex="0"
    :aria-busy="store.loading"
    @scroll.passive="fillAvailableSpace"
  >
    <table>
      <thead>
        <tr>
          <th scope="col">ID</th>
          <th scope="col">Name</th>
          <th scope="col">Email</th>
        </tr>
      </thead>

      <tbody>
        <tr v-for="row in store.rows" :key="row.id">
          <td>{{ row.id }}</td>
          <td>{{ row.name }}</td>
          <td>{{ row.email }}</td>
        </tr>
      </tbody>
    </table>

    <div class="status" aria-live="polite">
      <span v-if="store.loading">Loading…</span>

      <template v-else-if="store.error">
        {{ store.error }}
        <button type="button" @click="retry">Retry</button>
      </template>

      <span v-else-if="!store.hasMore">
        {{ store.rows.length ? 'All rows loaded.' : 'No records.' }}
      </span>
    </div>
  </div>
</template>

