    // bottom threshold, or the API has no more rows.
    while (
      active &&
      needsMoreRows() &&
      store.hasMore &&
      !store.loading &&
      !store.error
    ) {
      await store.fetchNext()
      await nextTick()
    }
  } finally {
    checking = false
  }
}

function retry() {
