Scores below \(10^{100}\), and their totals, do not fit in built-in integer types. With a compiler that provides Boost, use `boost::multiprecision::cpp_int` for arbitrary-precision integers:

```cpp
#include <iostream>
#include <string>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    cpp_int totals[2] = {0, 0};

    for (int archer = 0; archer < 2; ++archer) {
        for (int i = 0; i < n; ++i) {
            string s;
            cin >> s;

            // Parse as decimal, including inputs with leading zeros.
            cpp_int score = 0;
            for (char digit : s) {
                score = score * 10 + (digit - '0');
            }
            totals[archer] += score;
        }
    }

    cout << (totals[0] > totals[1] ? "one" : "two") << '\n';
    return 0;
}
```

This processes scores directly without storing the arrays. Manual string arithmetic is another valid solution if Boost is unavailable.

