    cpp_int total = 0;

    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;

        // Parse explicitly as decimal, including any leading zeros.
        cpp_int score = 0;
        for (char digit : s) {
            score *= 10;
            score += digit - '0';
        }

        total += score;
    }

    return total;
}

