题目要求使用 `strlen`，但又说“不能用系统函数”，两者有些矛盾。下面理解为：**允许使用题目指定的 `strlen` 和基本输入输出，不使用其他库函数或自定义函数。**

```cpp
#include <iostream>
#include <cstring>
using namespace std;

int main() {
    char a[101];
    int num[101];
    int b;

    cin >> a >> b;

    int n = strlen(a);

    // 将字符数组中的每一位转换为整数
    for (int i = 0; i < n; i++) {
        num[i] = a[i] - '0';
    }

    // 从个位开始相加
    int carry = b;
    for (int i = n - 1; i >= 0; i--) {
        num[i] += carry;
        if (num[i] >= 10) {
            num[i] -= 10;
            carry = 1;
        } else {
            carry = 0;
        }
    }

    // 最高位可能产生一个进位
    if (carry == 1) {
        cout << 1;
    }

    for (int i = 0; i < n; i++) {
        cout << num[i];
    }
    cout << '\n';

    return 0;
}
```

每位相加的结果最多为 18，因此发生进位时减去一次 10 即可。时间复杂度为 `O(n)`，能够处理 `99 + 9 = 108` 等增加位数的情况。

