使用 **扫描线 + y 坐标离散化 + 线段树**。

将每个矩形拆成两个事件：在左边界加入对应的 y 区间，在右边界移除。按照 x 坐标从小到大处理事件，线段树维护当前 y 方向的覆盖总长度。

每次处理事件前，先累加：
\[
\text{面积贡献}=(x-\text{上一个事件的 }x)\times \text{当前覆盖长度}
\]

线段树节点表示离散化后的区间 `[ys[l], ys[r])`：
- 覆盖计数大于 0：覆盖长度为 `ys[r] - ys[l]`。
- 覆盖计数为 0：叶节点长度为 0，非叶节点合并两个子节点的长度。

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

using ll = long long;
constexpr ll MOD = 1000000007LL;

struct Event {
    ll x, y1, y2;
    int delta;
};

class SegmentTree {
    vector<ll> ys, len;
    vector<int> cnt;
    int n;

    void update(int p, int l, int r, int ql, int qr, int delta) {
        if (qr <= l || r <= ql) return;

        if (ql <= l && r <= qr) {
            cnt[p] += delta;
        } else {
            int mid = (l + r) / 2;
            update(p * 2, l, mid, ql, qr, delta);
            update(p * 2 + 1, mid, r, ql, qr, delta);
        }

        if (cnt[p] > 0) {
            len[p] = ys[r] - ys[l];
        } else if (r - l == 1) {
            len[p] = 0;
        } else {
            len[p] = len[p * 2] + len[p * 2 + 1];
        }
    }

public:
    explicit SegmentTree(const vector<ll>& coordinates)
        : ys(coordinates) {
        n = static_cast<int>(ys.size()) - 1;
        len.assign(4 * n + 4, 0);
        cnt.assign(4 * n + 4, 0);
    }

    void update(int l, int r, int delta) {
        update(1, 0, n, l, r, delta);
    }

    ll coveredLength() const {
        return len[1];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Event> events;
    vector<ll> ys;

    for (int i = 0; i < n; ++i) {
        ll x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;

        // 零面积矩形不影响结果。
        if (x1 == x2 || y1 == y2) continue;

        events.push_back({x1, y1, y2, 1});
        events.push_back({x2, y1, y2, -1});
        ys.push_back(y1);
        ys.push_back(y2);
    }

    if (events.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    sort(events.begin(), events.end(),
         [](const Event& a, const Event& b) {
             return a.x < b.x;
         });

    SegmentTree tree(ys);
    ll answer = 0;
    ll prevX = events.front().x;

    for (const auto& e : events) {
        ll dx = e.x - prevX;
        answer = (answer + dx * tree.coveredLength()) % MOD;

        int l = lower_bound(ys.begin(), ys.end(), e.y1) - ys.begin();
        int r = lower_bound(ys.begin(), ys.end(), e.y2) - ys.begin();
        tree.update(l, r, e.delta);

        prevX = e.x;
    }

    cout << answer << '\n';
    return 0;
}
```

相同 x 坐标的事件可以逐个处理，因为它们之间的宽度为 0，不会额外产生面积。坐标不超过 \(10^9\)，单次面积乘积不超过 \(10^{18}\)，使用 `long long` 安全。

**时间复杂度：** \(O(n\log n)\)。  
**空间复杂度：** \(O(n)\)。

