## 我的答案

使用**扫描线 + 线段树**：

- 每个矩形产生两个事件：在 `x1` 加入区间 `[y1,y2)`，在 `x2` 删除该区间。
- 将所有 y 坐标排序去重，线段树维护相邻 y 坐标构成的区间。
- 线段树根节点记录当前 y 方向的覆盖总长度。
- 扫描到下一个 x 坐标时，先累加面积：`横向距离 × 当前覆盖总长度`，再处理该位置的事件。

宽或高为零的矩形不贡献面积，可以直接忽略。

```cpp
#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

struct Event {
    ll x, y1, y2;
    int delta;
};

class SegmentTree {
    int n;
    vector<int> cnt;
    vector<ll> len, ys;

    void pull(int p, int l, int r) {
        if (cnt[p] > 0) {
            len[p] = ys[r] - ys[l];
        } else if (r - l == 1) {
            len[p] = 0;
        } else {
            len[p] = len[p * 2] + len[p * 2 + 1];
        }
    }

    void update(int p, int l, int r, int ql, int qr, int delta) {
        if (qr <= l || r <= ql) return;

        if (ql <= l && r <= qr) {
            cnt[p] += delta;
        } else {
            int mid = (l + r) / 2;
            update(p * 2, l, mid, ql, qr, delta);
            update(p * 2 + 1, mid, r, ql, qr, delta);
        }
        pull(p, l, r);
    }

public:
    explicit SegmentTree(const vector<ll>& coordinates)
        : n((int)coordinates.size() - 1),
          cnt(4 * n + 4, 0),
          len(4 * n + 4, 0),
          ys(coordinates) {}

    void update(int l, int r, int delta) {
        if (l < r) update(1, 0, n, l, r, delta);
    }

    ll coveredLength() const {
        return len[1];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Event> events;
    vector<ll> ys;

    for (int i = 0; i < n; ++i) {
        ll x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;

        if (x1 == x2 || y1 == y2) continue;

        events.push_back({x1, y1, y2, 1});
        events.push_back({x2, y1, y2, -1});
        ys.push_back(y1);
        ys.push_back(y2);
    }

    if (events.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    sort(events.begin(), events.end(),
         [](const Event& a, const Event& b) {
             return a.x < b.x;
         });

    SegmentTree tree(ys);
    ll ans = 0;
    ll prevX = events.front().x;

    for (size_t i = 0; i < events.size();) {
        ll x = events[i].x;
        ans = (ans + (x - prevX) * tree.coveredLength()) % MOD;

        while (i < events.size() && events[i].x == x) {
            int l = lower_bound(ys.begin(), ys.end(), events[i].y1)
                    - ys.begin();
            int r = lower_bound(ys.begin(), ys.end(), events[i].y2)
                    - ys.begin();

            tree.update(l, r, events[i].delta);
            ++i;
        }
        prevX = x;
    }

    cout << ans << '\n';
    return 0;
}
```

坐标不超过 `10^9`，单次面积乘积不超过 `10^18`，使用 `long long` 安全。

**时间复杂度：** `O(n log n)`。  
**空间复杂度：** `O(n)`。

