using namespace std;

using ll = long long;

bool check(ll a, ll b, ll c, ll k) {
    while (a || b || c) {
        if ((a % k + b % k) % k != c % k)
            return false;
        a /= k;
        b /= k;
        c /= k;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        ll a, b, c;
        cin >> a >> b >> c;

        ll d = a + b - c;
        if (d < 0) {
            cout << 0 << '\n';
            continue;
        }
        if (d == 0) {
            cout << -1 << '\n';
            continue;
        }

