    % 保留原有角度相关惩罚项；它不是严格的实际运动能耗。
    motion_penalty = sum(joint_inertia .* ...
                         (joint_avg_speed .* theta).^2);

    f = [position_error, motion_penalty + gravitational_energy];
end

function disp_results(x, fval)
    if isempty(x) || isempty(fval)
        disp('本次运行未返回可显示的解。');
        return;
