    candidates = find(fval(:,1) <= 1.1 * minError);
    if isempty(candidates)
        disp('未找到符合所设规则的均衡点。');
    else
        [~, localIdx] = min(fval(candidates,2));
        balancedIdx = candidates(localIdx);
        show_solution('均衡点', x, fval, balancedIdx);
    end
end

function show_solution(name, x, fval, idx)
    disp([name, ' - 关节角度（度）：']);
    disp(array2table(rad2deg(x(idx,:)), ...
        'VariableNames', ...
